// ==== Baukasten Oberfläche (BA3, ALLY 21) – Kern. Reine Funktion: Seitenbeschreibung (JSON) -> HTML. ====
// Migration 78 (Stefan 21.10.2026, 19:47): Überblick klappbar (U.klappbar), Karten mit unter, Auswahl der Bausteine beim Anordnen (startseite.ueberblick_auswahl).
// Eingabe: { version: 1, basis, rahmen: { produkt, cd, person, kopf, leiste, zustand, texte, sicherheit }, inhalt: { seite, ueberblick, abschnitte, startseite, fenster, hinweis } }
// Regeln: alle Texte aus der Eingabe, alles HTML-escapt; Links nur aus Zielen ({ seite, parameter, anker }); Farben/Schrift/Logo nur aus CD 1;
// kein iframe; Zustände per POST (303) bzw. Feld _z / Parameter z bei der nächsten Navigation. Runde 2 (Stefan 21.10.2026): Klappzustand zusätzlich sofort per
// fetch (no-cors, keepalive) an <basis>/aktion mit aktion=ui_zustand; ALLY 20 antwortet dafür mit 204 ohne Weiterleitung.
// Migration 209 (Fehler 46, Stefan 06.11.2026): Adressen ohne ?seite= – Seite und Objekt stehen im Pfad. Zuordnung aus der Datenbank (Tabelle ally_ui_pfade,
// Liste ally_ui_pfade_liste: m = Muster, s = Seitenschlüssel, f = feste Parameter, r = übrige Parameter als Abfrage). Gleiche Regeln wie ally_ui_pfad und die
// Web-App (webapp/src/pfade.ts): es zählt das Muster mit den meisten festen Parametern und Kennungen; Filter, Ansicht und Blättern stehen nicht im Pfad.
const PFAD_FREI = ['start', 'unbekannt', 'aktion', 'datei', 'manifest', 'symbol', 'kalender', 'stil', 'skript', 'logo', 'neu', 'api', 'mediakit', 'webhook'];
const PFAD_TEIL = v => encodeURIComponent(String(v)).replace(/%40/g, '@').replace(/%3A/g, ':');
// Migration 210 (Stefan 06.11.2026 „Name“, „Nummern sollen nirgends sichtbar sein“): Kennungen der Objekte (ally_ui_kennungen_karte: [Seite, Parameter,
// Nummer, Kennung] bzw. mit Bereich [… , Bereichsparameter, Bereichsnummer]). Mit PFAD_KENNUNGEN_SETZEN gesetzt, tragen Pfade die Kennung statt der Nummer.
let PFAD_KARTE = new Map(), PFAD_BEREICH = new Map();
const PFAD_KENNUNGEN_SETZEN = l => {
  PFAD_KARTE = new Map(); PFAD_BEREICH = new Map();
  for (const e of Array.isArray(l) ? l : []) {
    if (!Array.isArray(e) || e.length < 4 || !e.slice(0, 4).every(x => typeof x === 'string')) continue;
    const bp = typeof e[4] === 'string' ? e[4] : '';
    if (bp) PFAD_BEREICH.set(e[0] + '|' + e[1], bp);
    PFAD_KARTE.set(e[0] + '|' + e[1] + '|' + e[2] + '|' + (bp ? String(e[5] ?? '') : ''), e[3]);
  }
};
const PFAD_KENNUNG = (seite, k, P) => {
  const bp = PFAD_BEREICH.get(seite + '|' + k);
  const w = PFAD_KARTE.get(seite + '|' + k + '|' + P[k] + '|' + (bp ? String(P[bp] ?? '') : ''));
  return w === undefined ? P[k] : w;
};
const PFAD_FINDEN = (liste, seite, P0) => {
  const P = {};
  for (const k of Object.keys(P0 || {})) { const v = P0[k]; if (v !== undefined && v !== null && typeof v !== 'object' && String(v) !== '') P[k] = String(v); }
  let b = null, bs = -1;
  for (const r of Array.isArray(liste) ? liste : []) {
    if (!r || r.s !== seite || typeof r.m !== 'string') continue;
    const f = r.f && typeof r.f === 'object' ? r.f : {};
    if (Object.keys(f).some(k => P[k] !== String(f[k]))) continue;
    const ph = (r.m.match(/\{[a-z0-9_]+\}/g) || []).map(x => x.slice(1, -1));
    if (ph.some(k => !/^[^\/\x00-\x1f\x7f]{1,200}$/.test(P[k] || ''))) continue;
    const sc = Object.keys(f).length + ph.length;
    if (sc > bs) { b = r; bs = sc; }
  }
  if (!b) return { pfad: /^[a-z0-9-]{1,40}$/.test(String(seite)) && !PFAD_FREI.includes(seite) ? '/' + seite : '/', genutzt: [], rest: false };
  const ph = (b.m.match(/\{[a-z0-9_]+\}/g) || []).map(x => x.slice(1, -1));
  return { pfad: b.m.replace(/\{([a-z0-9_]+)\}/g, (_, k) => PFAD_TEIL(PFAD_KENNUNG(seite, k, P))), genutzt: Object.keys(b.f || {}).concat(ph), rest: b.r === true };
};
const PFAD_BAUEN = (liste, seite, P) => {
  const x = PFAD_FINDEN(liste, seite, P);
  const rest = x.rest ? Object.keys(P || {}).filter(k => !x.genutzt.includes(k) && P[k] !== undefined && P[k] !== null && String(P[k]) !== '').sort() : [];
  return x.pfad + (rest.length ? '?' + rest.map(k => PFAD_TEIL(k) + '=' + PFAD_TEIL(P[k])).join('&') : '');
};
// bisherige Adresse „/?seite=…&…#anker“ (nur Basis /) als Pfad; die Meldung m bleibt als Abfrage. Ohne Zuordnung unverändert (ALLY 20 leitet dann um).
const ADRESSE_NEU = (liste, url) => {
  const m = String(url || '').match(/^\/\?([^#]*)(#.*)?$/);
  if (!m || !Array.isArray(liste) || !liste.length) return url;
  const q = new URLSearchParams(m[1]), P = {};
  q.forEach((v, k) => { if (k !== 'seite' && k !== 'm') P[k] = v; });
  const pfad = PFAD_BAUEN(liste, q.get('seite') || 'start', P), mm = q.get('m') || '';
  return pfad + (/^[a-z]{1,20}$/.test(mm) ? (pfad.includes('?') ? '&' : '?') + 'm=' + mm : '') + (m[2] || '');
};
// Migration 210 (Stefan 06.11.2026 „Name“): Kennungen für die Links dieses Knotens
try { PFAD_KENNUNGEN_SETZEN((($('Start').first().json || {}).rahmen || {}).kennungen); } catch (e) { /* ohne Kennungen: Nummern (ALLY 20 leitet um) */ }
function baueSeite(E) {
  'use strict';
  if (!E || typeof E !== 'object') throw new Error('Baukasten: keine Eingabe.');
  if (E.version !== 1) throw new Error('Baukasten: unbekannte Version ' + String(E.version) + '.');
  const R = E.rahmen || {}, I = E.inhalt || {}, S = I.seite || {};

  // ---------- Grundfunktionen ----------
  const h = v => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
  const at = (k, v) => v === undefined || v === null || v === false || v === '' ? '' : ' ' + k + (v === true ? '' : '="' + h(v) + '"');
  const fehler = t => { throw new Error('Baukasten: ' + t); };
  const RE = { seite: /^[a-z0-9-]{1,40}$/, param: /^[a-z0-9_]{1,30}$/, id: /^[a-z0-9-]{1,40}$/, name: /^[a-z0-9_]{1,40}$/, farbe: /^#[0-9a-fA-F]{6}$/, schrift: /^[A-Za-z0-9 ]{1,60}$/,
    bild: /^data:image\/(svg\+xml|png);base64,[A-Za-z0-9+/]+={0,2}$/, vorschau: /^data:image\/(svg\+xml|png|jpeg);base64,[A-Za-z0-9+/]+={0,2}$/, basis: /^\/([A-Za-z0-9_-]+(\/[A-Za-z0-9_-]+)*)?$/, aktion: /^[a-z0-9_]{1,60}$/,
    // Content-Galerie (Stefan 21.10.2026): Vorschaubilder der Plattformen nur als https-Adresse (CSP img-src https:), ohne Anführungszeichen, Klammern und Leerzeichen
    extbild: /^https:\/\/[A-Za-z0-9.-]{3,253}(:[0-9]{1,5})?\/[^\s<>"'\\`]{0,2000}$/ };
  const pruefe = (re, v, was) => { if (typeof v !== 'string' || !re.test(v)) fehler('ungültige(r) ' + was + ': ' + JSON.stringify(v)); return v; };
  const TX = R.texte || {};
  // Sichtbare Texte des Rahmens: aus rahmen.texte, Platzhalter {x}. Fehlt ein Text, steht ⟦schlüssel⟧ sichtbar auf der Seite (kein stiller Ersatz).
  const T = (k, w) => { const t = TX[k]; if (typeof t !== 'string') return '⟦' + k + '⟧'; return t.replace(/\{([a-z_]+)\}/g, (m, x) => w && w[x] !== undefined ? String(w[x]) : m); };
  // Neue Rahmentexte (Stefan 21.10.2026, 14:13–14:19) mit festem Rückfall, bis sie in rahmen.texte stehen
  const TD = (k, d, w) => typeof TX[k] === 'string' ? T(k, w) : String(d).replace(/\{([a-z_]+)\}/g, (m, x) => w && w[x] !== undefined ? String(w[x]) : m);
  const BASIS = pruefe(RE.basis, E.basis, 'Basis-Pfad');
  const AKTION = (BASIS === '/' ? '' : BASIS) + '/aktion';
  const DATEI = (BASIS === '/' ? '' : BASIS) + '/datei';
  const SK = S.schluessel ? pruefe(RE.seite, S.schluessel, 'Seitenschlüssel') : 'start';
  const CSRF = String((R.sicherheit || {}).csrf || '');
  const Z = R.zustand && typeof R.zustand === 'object' ? R.zustand : {};
  const ZTEIL = S.zustand_teil ? pruefe(RE.id, S.zustand_teil, 'Zustand-Teil') : '';

  // Ziel -> Adresse. Ziel = { seite, parameter: { name: Wert }, anker }; nie eine fertige URL.
  const adresse = (ziel, extra) => {
    if (!ziel || typeof ziel !== 'object') fehler('Ziel fehlt.');
    const teile = [];
    const seite = ziel.seite === undefined ? 'start' : pruefe(RE.seite, ziel.seite, 'Seite');
    if (seite !== 'start') teile.push('seite=' + encodeURIComponent(seite));
    const p = Object.assign({}, ziel.parameter || {}, extra || {});
    for (const k of Object.keys(p)) {
      pruefe(RE.param, k, 'Parametername');
      if (k === 'seite') fehler('Parameter "seite" ist reserviert.');
      const v = p[k];
      if (v === undefined || v === null || v === '') continue;
      if (!['string', 'number', 'boolean'].includes(typeof v)) fehler('Parameter ' + k + ' ist kein einfacher Wert.');
      teile.push(k + '=' + encodeURIComponent(String(v)));
    }
    const anker = ziel.anker ? '#' + pruefe(RE.id, ziel.anker, 'Anker') : '';
    // Migration 209 (Fehler 46, Stefan 06.11.2026): auf der eigenen Adresse (Basis /) Seite und Objekt als Pfad (Zuordnung rahmen.pfade aus der Datenbank); was der Pfad nicht aufnimmt
    // (Klappzustand, Sortierung, Blättern dieser Seiten ohne Web-App), bleibt als Abfrage
    if (BASIS === '/' && Array.isArray(R.pfade) && R.pfade.length) {
      const P2 = {}; for (const k of Object.keys(p)) if (p[k] !== undefined && p[k] !== null && p[k] !== '') P2[k] = String(p[k]);
      const x = PFAD_FINDEN(R.pfade, seite, P2);
      const rest = Object.keys(P2).filter(k => !x.genutzt.includes(k)).map(k => k + '=' + encodeURIComponent(P2[k]));
      return x.pfad + (rest.length ? '?' + rest.join('&') : '') + anker;
    }
    return BASIS + (teile.length ? '?' + teile.join('&') : '') + anker;
  };
  // Aktuelle Seite (für Formular-Rücksprung und Tabellen-Links); s, p, z, f gehören nicht zur Seite selbst
  const seitenParameter = () => { const p = Object.assign({}, S.parameter || {}); for (const k of ['s', 'p', 'z', 'f']) delete p[k]; return p; };
  const hier = (anker, extra) => adresse({ seite: SK, parameter: seitenParameter(), anker }, extra);

  // ---------- Corporate Design (CD 1) ----------
  const CD = R.cd || fehler('Corporate Design fehlt.');
  const F0 = CD.farben || {};
  const FN = ['dunkel', 'textAufDunkel', 'akzent', 'akzentDunkel', 'hell', 'grau', 'warnung'];
  const F = {};
  for (const n of FN) F[n] = pruefe(RE.farbe, F0[n], 'CD-Farbe ' + n).toUpperCase();
  const schrift = pruefe(RE.schrift, CD.schrift, 'CD-Schrift');
  // Abstufungen wie in CD 1 aus den Grundfarben gemischt (nicht aus der Eingabe übernommen)
  const rgb = x => [1, 3, 5].map(i => parseInt(x.slice(i, i + 2), 16));
  const hex = a => '#' + a.map(v => Math.round(Math.max(0, Math.min(255, v))).toString(16).padStart(2, '0')).join('').toUpperCase();
  const mische = (a, b, t) => { const x = rgb(a), y = rgb(b); return hex(x.map((v, i) => v + (y[i] - v) * t)); };
  const L = CD.logos || {};
  const bild = n => typeof L[n] === 'string' && RE.bild.test(L[n]) ? L[n] : null;
  const logoGross = bild('logo_fuer_dunkel'), logoKlein = bild('bildmarke_fuer_dunkel') || logoGross;
  const PRODUKT = String(R.produkt || '');

  // ---------- Symbole (nur Formen, Farbe über currentColor) ----------
  const svg = (d, g) => '<svg class="sym" width="' + (g || 20) + '" height="' + (g || 20) + '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">' + d + '</svg>';
  const SYM = {
    // Runde 2 (Stefan 21.10.2026): externer Link (Pfeil nach rechts oben)
    extern: '<path d="M7 17 17 7"/><path d="M8 7h9v9"/>',
    glocke: '<path d="M6 8a6 6 0 1 1 12 0c0 7 3 8 3 8H3s3-1 3-8"/><path d="M10 20a2 2 0 0 0 4 0"/>',
    zahnrad: '<path d="M12.22 2h-.44a2 2 0 0 0-2 2v.18a2 2 0 0 1-1 1.73l-.43.25a2 2 0 0 1-2 0l-.15-.08a2 2 0 0 0-2.73.73l-.22.38a2 2 0 0 0 .73 2.73l.15.1a2 2 0 0 1 1 1.72v.51a2 2 0 0 1-1 1.74l-.15.09a2 2 0 0 0-.73 2.73l.22.38a2 2 0 0 0 2.73.73l.15-.08a2 2 0 0 1 2 0l.43.25a2 2 0 0 1 1 1.73V20a2 2 0 0 0 2 2h.44a2 2 0 0 0 2-2v-.18a2 2 0 0 1 1-1.73l.43-.25a2 2 0 0 1 2 0l.15.08a2 2 0 0 0 2.73-.73l.22-.39a2 2 0 0 0-.73-2.73l-.15-.08a2 2 0 0 1-1-1.74v-.5a2 2 0 0 1 1-1.74l.15-.09a2 2 0 0 0 .73-2.73l-.22-.38a2 2 0 0 0-2.73-.73l-.15.08a2 2 0 0 1-2 0l-.43-.25a2 2 0 0 1-1-1.73V4a2 2 0 0 0-2-2z"/><circle cx="12" cy="12" r="3"/>',
    // Lucide "info", "circle-alert", "circle-check" (ISC-Lizenz)
    info: '<circle cx="12" cy="12" r="10"/><path d="M12 16v-4"/><path d="M12 8h.01"/>',
    warnung: '<circle cx="12" cy="12" r="10"/><line x1="12" x2="12" y1="8" y2="12"/><line x1="12" x2="12.01" y1="16" y2="16"/>',
    ok: '<circle cx="12" cy="12" r="10"/><path d="m9 12 2 2 4-4"/>',
    pfeil: '<path d="m6 9 6 6 6-6"/>', menue: '<path d="M4 7h16M4 12h16M4 17h16"/>', ki: '<path d="M4 19h16M7 16V9m5 7V5m5 11v-4"/>',
    zu: '<path d="M6 6l12 12M18 6 6 18"/>', hoch: '<path d="m6 15 6-6 6 6"/>', runter: '<path d="m6 9 6 6 6-6"/>',
    griff: '<circle cx="9" cy="6" r="1.2"/><circle cx="15" cy="6" r="1.2"/><circle cx="9" cy="12" r="1.2"/><circle cx="15" cy="12" r="1.2"/><circle cx="9" cy="18" r="1.2"/><circle cx="15" cy="18" r="1.2"/>',
    standard: '<rect x="4" y="4" width="16" height="16" rx="3"/><path d="M8 12h8M8 8h5M8 16h6"/>',
    talents: '<circle cx="9" cy="8" r="3.5"/><path d="M2.5 20a6.5 6.5 0 0 1 13 0"/><path d="M16 4.5a3.5 3.5 0 0 1 0 7M18 14a6 6 0 0 1 3.5 6"/>',
    kampagnen: '<path d="M3 11v2a1 1 0 0 0 1 1h3l6 4V6L7 10H4a1 1 0 0 0-1 1z"/><path d="M17 8a5 5 0 0 1 0 8"/>',
    reports: '<path d="M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8z"/><path d="M14 3v5h5M9 17v-3M12 17v-6M15 17v-2"/>',
    mail: '<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 7 9 6 9-6"/>',
    kalender: '<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/>',
    fragen: '<path d="M21 12a8 8 0 0 1-11.6 7.1L4 20l1-4.6A8 8 0 1 1 21 12z"/>',
    finanzen: '<path d="M17 6.5A7 7 0 1 0 17 17.5M4 10h9M4 14h9"/>',
    marketing: '<path d="M4 20V10M10 20V4M16 20v-7M22 20H2"/>',
    // Plattformen für die Metazeile im Seitenkopf (Stefan 21.10.2026): Lucide "instagram", "facebook", "youtube", "linkedin", "at-sign" (Threads) (ISC-Lizenz);
    // TikTok und Pinterest als einfache eigene Formen. Nur Umrisse in currentColor, der Name steht als title und aria-label daneben.
    pf_instagram: '<rect width="20" height="20" x="2" y="2" rx="5" ry="5"/><path d="M16 11.37A4 4 0 1 1 12.63 8 4 4 0 0 1 16 11.37z"/><line x1="17.5" x2="17.51" y1="6.5" y2="6.5"/>',
    pf_facebook: '<path d="M18 2h-3a5 5 0 0 0-5 5v3H7v4h3v8h4v-8h3l1-4h-4V7a1 1 0 0 1 1-1h3z"/>',
    pf_youtube: '<path d="M2.5 17a24.12 24.12 0 0 1 0-10 2 2 0 0 1 1.4-1.4 49.56 49.56 0 0 1 16.2 0A2 2 0 0 1 21.5 7a24.12 24.12 0 0 1 0 10 2 2 0 0 1-1.4 1.4 49.55 49.55 0 0 1-16.2 0A2 2 0 0 1 2.5 17"/><path d="m10 15 5-3-5-3z"/>',
    pf_linkedin: '<path d="M16 8a6 6 0 0 1 6 6v7h-4v-7a2 2 0 0 0-2-2 2 2 0 0 0-2 2v7h-4v-7a6 6 0 0 1 6-6z"/><rect width="4" height="12" x="2" y="9"/><circle cx="4" cy="4" r="2"/>',
    pf_threads: '<circle cx="12" cy="12" r="4"/><path d="M16 8v5a3 3 0 0 0 6 0v-1a10 10 0 1 0-4 8"/>',
    pf_tiktok: '<path d="M14 3v11.5a4.5 4.5 0 1 1-4.5-4.5"/><path d="M14 3a5 5 0 0 0 5 5"/>',
    pf_pinterest: '<circle cx="12" cy="12" r="10"/><path d="M11 8.5c3.5-1.5 6 .5 5.5 3.5-.4 2.6-3 3.6-4.5 2.5M12 11l-2.5 10"/>',
    // Lucide "lock" (ISC-Lizenz): Abschnitt oder Formular nur für Superadmins sichtbar (schloss: true; Punkt 20/22, Stefan 21.10.2026, 09:33)
    schloss: '<rect width="18" height="11" x="3" y="11" rx="2" ry="2"/><path d="M7 11V7a5 5 0 0 1 10 0v4"/>',
    pf_andere: '<circle cx="12" cy="12" r="10"/><path d="M2 12h20M12 2a15 15 0 0 1 0 20M12 2a15 15 0 0 0 0 20"/>'
  };
  const sym = (n, g) => svg(SYM[n] || SYM.standard, g);

  // ---------- Bausteine: kleine Teile ----------
  const TOENE = ['ok', 'warn', 'grau', 'info'];
  const ton = t => TOENE.includes(t) ? ' ' + t : '';
  const marke = m => m && m.text ? '<span class="marke' + ton(m.ton) + '">' + h(m.text) + '</span>' : '';
  const versteckt = (n, v) => '<input type="hidden" name="' + h(n) + '" value="' + h(v) + '">';
  const postKopf = (aktion, zurueckAnker, werte, opt) => {
    const o = opt || {};
    pruefe(RE.aktion, aktion, 'Aktion');
    let s = '<form method="post" action="' + h(o.datei ? DATEI : AKTION) + '"' + (o.datei ? ' enctype="multipart/form-data"' : '') + at('class', o.klasse) + at('id', o.id) +
      at('data-frage', o.frage) + at('aria-label', o.label) + (o.erst ? ' data-erst-speichern="fo-' + h(pruefe(RE.id, o.erst, 'Formular-ID')) + '"' + at('data-erst-frage', o.erst_frage) + at('data-erst-danach', /^[a-z_]{1,20}$/.test(String(o.erst_danach || '')) ? o.erst_danach : '') : '') + (o.merken ? ' data-merken' : '') + '>' + versteckt('aktion', aktion) + versteckt('csrf', CSRF) + versteckt('zurueck', o.zurueck || hier(zurueckAnker));
    for (const k of Object.keys(werte || {})) { pruefe(RE.name, k, 'Feldname'); if (['aktion', 'csrf', 'zurueck', '_z'].includes(k)) fehler('Feldname ' + k + ' ist reserviert.'); s += versteckt(k, werte[k]); }
    return s;
  };
  // Runde 2 (Stefan 21.10.2026): externer Link – nur https, öffnet in einem neuen Tab (target _blank, rel noopener noreferrer), mit Pfeil-Symbol und Hinweis für Screenreader.
  // Ungültige Adresse: kein Link, nur der Text.
  const EXT = /^https:\/\/[A-Za-z0-9.-]{3,253}(:[0-9]{1,5})?(\/[^\s<>"'\\`]{0,2000})?$/;
  const externLink = (url, text, kl, lab) => { const u = String(url || '').trim();
    if (!EXT.test(u)) return text ? '<span' + at('class', kl === 'textknopf' ? 'ext-aus' : '') + '>' + h(text) + '</span>' : '';
    return '<a class="' + (kl || 'textknopf') + ' extern" href="' + h(u) + '" target="_blank" rel="noopener noreferrer"' + at('aria-label', lab ? lab + ' (' + T('neuer_tab') + ')' : '') + '>' + h(text || u) +
      '<span class="sr"> (' + h(T('neuer_tab')) + ')</span>' + sym('extern', 14) + '</a>'; };
  // Abnahme-Korrektur (Stefan 21.10.2026): Ziel mit neuer_tab = interne geprüfte Weiterleitung (Seite „link“) zu einer fremden Seite – neuer Tab, Pfeil, ohne Verweis-Angabe
  const zielLink = (z, kl, text, attr) => z && z.neuer_tab === true
    ? '<a class="' + kl + ' extern" href="' + h(adresse(z)) + '" target="_blank" rel="noopener noreferrer"' + (attr || '') + '>' + h(text) + '<span class="sr"> (' + h(T('neuer_tab')) + ')</span>' + sym('extern', 14) + '</a>'
    : '<a class="' + kl + '" href="' + h(adresse(z)) + '"' + (attr || '') + '>' + h(text) + '</a>';
  // Aktion = { text, ziel } (Link) | { text, fenster } (öffnet Fenster) | { text, aktion, werte, frage } (POST) | { text, extern } (externer https-Link, Runde 2); art: haupt | neben | link
  const aktionsElement = (a, standardArt, anker) => {
