        '<button type="submit" class="knopf neben icon" name="gruppe_schieben" value="' + h(gid) + ':runter"' + (gi === gruppen.length - 1 ? ' disabled' : '') + ' aria-label="' + h(T('gruppe_nach_unten', { name: x.g.name })) + '" title="' + h(T('gruppe_nach_unten', { name: x.g.name })) + '">' + sym('runter', 18) + '</button>' +
        '</span></div><div class="kacheln anordnen" data-gruppe="' + gid + '">' + x.k.map(kachel).join('') + '</div></section>'; return; }
      s += '<details class="start-gruppe" data-z="start.' + gid + '"' + (offenZustand('start.' + gid, true) ? ' open' : '') + '><summary><h2>' + h(x.g.name) + '</h2>' + (x.g.info ? '<span class="g-info">' + h(x.g.info) + '</span>' : '') +
